package main

import "fmt"

type Counter struct {
    Value int
}

func (counter *Counter) Add(delta int) {
    counter.Value += delta
}

func main() {
    counter := &Counter{}
    for _, value := range []int{1, 2, 3} {
        counter.Add(value)
    }
    fmt.Println(counter.Value)
}

